fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // tol is strictly positive by assumption; no need to check here.
    // Calculate absolute difference safely by converting to i16.
    let diff = (a as i16) - (b as i16);
    diff > -(tol as i16) && diff < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions: a.len() == b.len() > 0 and tol > 0.
    // We map element-wise, calling is_close_i8 on pairs.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| is_close_i8(x, y, tol))
     .collect()
}